{
  "findings": [
    {
      "ref": "[D532]",
      "area": "contact",
      "claim": "A parent reports that strangers can message or voice chat with your child on Roblox.",
      "stance": "risk",
      "quote": "Some scams may use realistic images, videos or messages that appear to come from trusted creators or Roblox itself."
    },
    {
      "ref": "[D532]",
      "area": "contact",
      "claim": "Contact with strangers can be turned off using parental controls.",
      "stance": "mitigation",
      "quote": "Roblox offers parental controls that allow parents to manage content restrictions, communication settings, screen time and spending through a linked parent account."
    },
    {
      "ref": "[D532]",
      "area": "money",
      "claim": "A parent reports that Roblox pushes in-app purchases of Robux that can lead to unintended spending.",
      "stance": "risk",
      "quote": "Many experiences encourage players to spend Robux on virtual items, upgrades, customisation options and premium features."
    },
    {
      "ref": "[D532]",
      "area": "money",
      "claim": "A parent reports that Roblox uses loot‑box‑style random virtual items that may resemble gambling.",
      "stance": "risk",
      "quote": "Some experts have raised concerns that loot boxes can encourage repeated spending because players do not know what reward they will receive."
    },
    {
      "ref": "[D532]",
      "area": "money",
      "claim": "A parent reports that Roblox requires creators to disclose odds for random virtual items.",
      "stance": "mitigation",
      "quote": "The Terms of Use state that Creators who offer random virtual items must state the odds of each type of item a user might receive."
    },
    {
      "ref": "[D532]",
      "area": "data",
      "claim": "A parent reports that Roblox collects personal data and may share it with third parties for advertising.",
      "stance": "risk",
      "quote": "Roblox uses age assurance and verification measures for some features, alongside parental controls and content restrictions, to help create age‑appropriate experiences for younger users."
    },
    {
      "ref": "[D532]",
      "area": "data",
      "claim": "A parent reports that data can be deleted by the user or parent.",
      "stance": "mitigation",
      "quote": "You can [use spending controls] to help manage purchases."
    },
    {
      "ref": "[D532]",
      "area": "age_gating",
      "claim": "A parent reports that Roblox automatically assigns age‑based accounts and verifies age for certain features.",
      "stance": "mitigation",
      "quote": "Users are automatically assigned to an account type based off the age they input when creating a profile. Anyone who doesn’t verify their age is assigned to a Roblox Kids account."
    },
    {
      "ref": "[D532]",
      "area": "content",
      "claim": "A parent reports that children may see scam messages promising free Robux or exclusive items that look genuine.",
      "stance": "risk",
      "quote": "Some scams may use realistic images, videos or messages that appear to come from trusted creators or Roblox itself."
    },
    {
      "ref": "[D532]",
      "area": "developer_record",
      "claim": "A parent reports that Roblox has faced regulatory scrutiny for gambling‑like mechanics in the UK.",
      "stance": "risk",
      "quote": "Roblox has introduced additional restrictions for UK users under 18 around experiences that include paid random items, helping to limit younger users’ exposure to gambling‑like mechanics."
    }
  ]
}
